<script setup lang="ts">import{ref,onMounted}from 'vue';import{useRoute}from 'vue-router';import{lab,load}from '../stores/research';import{canEdit,isAdmin}from '../stores/auth';import*as notes from '../api/notes';import{download}from '../api/client';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';const route=useRoute(),run=ref(Number(route.query.run)||0),title=ref('独立时段流向补测说明'),interpretation=ref('结合两组圆周形状与置换前提，记录分布差异，不将均值方向或p值直接解释为成因。'),action=ref('保持方向标定，补采独立时段并核对流向采样的自相关。'),comment=ref('统计口径已核对，按独立采样协议继续观察。'),notice=ref(''),{error,execute}=useTask();onMounted(()=>execute(async()=>{await load();run.value=run.value||lab.runs.find(r=>r.status==='completed')?.id||0}));function create(){execute(async()=>{await notes.create({title:title.value,run_id:run.value,interpretation:interpretation.value,action:action.value});notice.value='观察说明已建立，等待负责人审阅';await load()})}function review(id:number,decision:string){execute(async()=>{await notes.review(id,decision,comment.value);await load();notice.value='审阅状态已保存'})}function exportNote(id:number){execute(()=>download('/notes/'+id+'/export','jijia-observation-'+id+'.csv'))}</script><template><PageHeading index="05" title="让统计线索，落到补测动作。" text="研究员起草，负责人审阅，阅读者只下载已批准说明。所有导出附输入指纹与方法边界。"/><ErrorNotice :message="error" @retry="execute(load)"/><p v-if="notice" class="success" role="status">{{notice}}</p><div class="notes-layout"><form v-if="canEdit" @submit.prevent="create"><p class="eyebrow">NEW OBSERVATION NOTE</p><label>关联研究<select v-model="run"><option v-for="r in lab.runs.filter(r=>r.status==='completed')" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>说明名称<input v-model="title" required minlength="3"></label><label>观察解释<textarea v-model="interpretation" rows="5" required minlength="8"/></label><label>补测动作<textarea v-model="action" rows="4" required minlength="5"/></label><button class="primary" :disabled="!run">保存观察说明 →</button></form><section><div class="section-title"><h2>观察档案</h2><span>{{lab.notes.length}}份</span></div><label v-if="isAdmin">审阅意见<textarea v-model="comment" rows="2"/></label><article v-for="n in lab.notes" class="observation-note"><div><p class="eyebrow">NOTE {{n.id}} / RUN {{n.run_id}}</p><StatusBadge :status="n.status"/></div><h2>{{n.title}}</h2><p>{{n.interpretation}}</p><p class="action-note">{{n.action}}</p><p v-if="n.review_comment" class="review-comment">{{n.approved_by}} · {{n.review_comment}}</p><div class="actions"><button v-if="isAdmin&&n.status==='draft'" class="primary" @click="review(n.id,'approved')">批准说明</button><button v-if="isAdmin&&n.status==='draft'" class="outline" @click="review(n.id,'rejected')">退回</button><button v-if="n.status==='approved'" class="outline" @click="exportNote(n.id)">下载获批CSV ↗</button></div></article></section></div></template>
